// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 block1, uint48 ts1, uint48 ts2, uint256 block2) public {
        vm.assume(ts2 > ts1);
        vm.assume(block1 != block2);
        vm.deal(address(this), 20 ether);
        vm.warp(ts1);
        vm.roll(block1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        vm.assume(ok1);
        vm.warp(ts2);
        vm.roll(block2);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2 || c.pastBlockTime() >= ts2);
    }
}
